#!/usr/bin/env bash
# Generated by ClickStarDeploy. Do not edit: it is rewritten on every apply.
# Speed-ups loaded into build.sh / deploy.sh through BASH_ENV:
# - npm / yarn / pnpm / composer installs are skipped when the lockfile (and runtime version and
#   command) is the same as in an earlier deploy: the dependencies installed then are copied
#   instead. Server: from a previous release. Runner: from a snapshot in the GitLab CI cache.
# - Next.js keeps its build cache (.next/cache) between deploys, so rebuilds are incremental.
# AD_ROOT is the release (server) or the checkout (runner); AD_STORE is set on the runner only.
# AD_NO_REUSE=1 turns all of it off.

# Folder of the current directory inside AD_ROOT ("." for the root); fails outside it.
_ad_rel() {
  local root here
  root=$(cd "${AD_ROOT:-${RELEASE_DIR:-/nonexistent}}" 2>/dev/null && pwd -P) || return 1
  here=$(pwd -P)
  case "$here" in
    "$root") printf '.' ;;
    "$root"/*) printf '%s' "${here#"$root"/}" ;;
    *) return 1 ;;
  esac
}

_ad_hash() { sha256sum | cut -c1-24; }

# Copy-on-write when the filesystem supports it (btrfs/xfs), a plain copy otherwise. Never hard
# links: build steps (prisma generate, caches) write into these files and must not touch the
# release that is serving traffic.
_ad_cp() {
  rm -rf "$2"
  cp -a --reflink=auto "$1" "$2" 2>/dev/null || { rm -rf "$2"; cp -a "$1" "$2"; }
}

# Earlier releases on the server, live one first.
_ad_prev_releases() {
  [ -n "${APP_DIR:-}" ] || return 0
  local cur self
  cur=$(readlink -f "$APP_DIR/current" 2>/dev/null || true)
  self=$(cd "${AD_ROOT:-${RELEASE_DIR:-/nonexistent}}" 2>/dev/null && pwd -P || true)
  if [ -n "$cur" ] && [ -d "$cur" ] && [ "$cur" != "$self" ]; then printf '%s\n' "$cur"; fi
  ls -1dt "$APP_DIR"/releases/*/ 2>/dev/null | sed 's#/$##' | grep -vxF -e "${cur:-/}" -e "${self:-/}" | head -n 4 || true
}

# Put back dependencies installed with the same key. $1 = dir (node_modules/vendor), $2 = key, $3 = rel.
_ad_restore() {
  local out=$1 key=$2 rel=$3 src r
  if [ -n "${AD_STORE:-}" ]; then
    src="$AD_STORE/deps/$(printf '%s' "$rel/$out" | _ad_hash)-$key.tar"
    [ -f "$src" ] || return 1
    rm -rf "$out"
    if tar -xf "$src" 2>/dev/null && [ -f "$out/.autodeploy-deps" ]; then return 0; fi
    rm -rf "$out"
    return 1
  fi
  while IFS= read -r r; do
    src="$r/$rel/$out"
    [ "$(cat "$src/.autodeploy-deps" 2>/dev/null)" = "$key" ] || continue
    if _ad_cp "$src" "$out"; then return 0; fi
  done < <(_ad_prev_releases)
  rm -rf "$out"
  return 1
}

# Runner only: one snapshot per folder, taken right after the install (before builds/prunes).
_ad_save() {
  [ -n "${AD_STORE:-}" ] || return 0
  local out=$1 key=$2 rel=$3 id
  id=$(printf '%s' "$rel/$out" | _ad_hash)
  mkdir -p "$AD_STORE/deps"
  rm -f "$AD_STORE/deps/$id"-*.tar
  tar -cf "$AD_STORE/deps/$id.tmp" "$out" && mv "$AD_STORE/deps/$id.tmp" "$AD_STORE/deps/$id-$key.tar" || rm -f "$AD_STORE/deps/$id.tmp"
}

# _ad_install <dir> <key text> <files that define the install...> -- <install command...>
_AD_REUSED=0
_ad_install() {
  local out=$1 info=$2 files=() f lock=0 rel key
  shift 2
  while [ $# -gt 0 ] && [ "$1" != -- ]; do files+=("$1"); shift; done
  shift
  _AD_REUSED=0
  for f in "${files[@]}"; do
    case $f in *lock*|*shrinkwrap*) if [ -f "$f" ]; then lock=1; fi ;; esac
  done
  if [ $lock = 0 ] || [ -n "${AD_NO_REUSE:-}" ] || [ -e "$out" ] || ! rel=$(_ad_rel); then "$@"; return; fi
  key=$({
    printf '%s\n' "$info"
    for f in "${files[@]}"; do
      if [ -f "$f" ]; then printf '== %s\n' "$f"; cat "$f"; fi
    done
    # Installs also generate from these (Prisma client, patch-package).
    find . \( -path ./node_modules -o -path ./vendor -o -path ./.git \) -prune -o -type f \
      \( -name '*.prisma' -o -path './patches/*' \) -print 2>/dev/null | LC_ALL=C sort | while IFS= read -r f; do
      printf '== %s\n' "$f"; cat "$f"
    done
  } | _ad_hash)
  if _ad_restore "$out" "$key" "$rel"; then
    _AD_REUSED=1
    echo "==> ClickStarDeploy: thư viện ở ${rel} không đổi so với lần trước, dùng lại bản đã cài (bỏ qua \"${*:2}\")"
    return 0
  fi
  "$@" || return
  if [ -d "$out" ]; then
    printf '%s\n' "$key" > "$out/.autodeploy-deps"
    _ad_save "$out" "$key" "$rel" || true
  fi
}

_ad_flags_only() {
  local a
  for a in "$@"; do case $a in -*) ;; *) return 1 ;; esac; done
}
_ad_workspaces() { grep -q '"workspaces"' package.json 2>/dev/null; }
# The project's own install hooks (postinstall: prisma generate, nuxt prepare...) after a reuse.
_ad_node_hooks() {
  [ "$_AD_REUSED" = 1 ] || return 0
  local s
  for s in preinstall install postinstall prepare; do
    if grep -q "\"$s\"[[:space:]]*:" package.json 2>/dev/null; then command npm run "$s" --if-present; fi
  done
}

# Next.js build cache. Runtime caches (images, fetch-cache) are left behind on purpose.
_ad_is_next() { ls next.config.* >/dev/null 2>&1 || grep -q '"next":' package.json 2>/dev/null; }
_ad_next_restore() {
  local rel=$1 src="" r d
  if [ -n "${AD_STORE:-}" ]; then
    src="$AD_STORE/next/$(printf '%s' "$rel" | _ad_hash)"
  else
    while IFS= read -r r; do
      if [ -d "$r/$rel/.next/cache" ]; then src="$r/$rel/.next/cache"; break; fi
    done < <(_ad_prev_releases)
  fi
  [ -n "$src" ] && [ -d "$src" ] || return 0
  mkdir -p .next/cache
  for d in "$src"/*; do
    [ -e "$d" ] || continue
    case ${d##*/} in images|fetch-cache) continue ;; esac
    [ -e ".next/cache/${d##*/}" ] || _ad_cp "$d" ".next/cache/${d##*/}"
  done
  echo "==> ClickStarDeploy: dùng lại cache build Next.js của lần trước"
}
_ad_next_save() {
  [ -n "${AD_STORE:-}" ] && [ -d .next/cache ] || return 0
  local dst d
  dst="$AD_STORE/next/$(printf '%s' "$1" | _ad_hash)"
  rm -rf "$dst"
  mkdir -p "$dst"
  for d in .next/cache/*; do
    [ -e "$d" ] || continue
    case ${d##*/} in images|fetch-cache) continue ;; esac
    cp -a "$d" "$dst/"
  done
}
_ad_build() {
  local rel
  if [ -n "${AD_NO_REUSE:-}" ] || ! _ad_is_next || ! rel=$(_ad_rel); then "$@"; return; fi
  _ad_next_restore "$rel" || true
  "$@" || return
  _ad_next_save "$rel" || true
}

npm() {
  case "${1:-}" in
    ci|install|i)
      if _ad_flags_only "${@:2}" && ! _ad_workspaces; then
        _ad_install node_modules "npm $* node=$(command node -v 2>/dev/null)" package.json package-lock.json npm-shrinkwrap.json -- command npm "$@" || return
        case " $* " in *" --ignore-scripts "*) ;; *) _ad_node_hooks ;; esac
        return
      fi ;;
    run|run-script)
      case "${2:-}" in build|build:*) _ad_build command npm "$@"; return ;; esac ;;
  esac
  command npm "$@"
}

yarn() {
  local sub=${1:-install}
  case $sub in -*) sub=install ;; esac
  case $sub in
    install)
      local args=("$@")
      [ "${1:-}" = install ] && args=("${@:2}")
      if [ ! -f .yarnrc.yml ] && ! _ad_workspaces && _ad_flags_only ${args[@]+"${args[@]}"}; then
        _ad_install node_modules "yarn $* yarn=$(command yarn --version 2>/dev/null) node=$(command node -v 2>/dev/null)" package.json yarn.lock -- command yarn "$@" || return
        case " $* " in *" --ignore-scripts "*) ;; *) _ad_node_hooks ;; esac
        return
      fi ;;
    build|build:*) _ad_build command yarn "$@"; return ;;
    run) case "${2:-}" in build|build:*) _ad_build command yarn "$@"; return ;; esac ;;
  esac
  command yarn "$@"
}

pnpm() {
  case "${1:-}" in
    install|i)
      if [ ! -f pnpm-workspace.yaml ] && _ad_flags_only "${@:2}"; then
        _ad_install node_modules "pnpm $* pnpm=$(command pnpm --version 2>/dev/null) node=$(command node -v 2>/dev/null)" package.json pnpm-lock.yaml -- command pnpm "$@" || return
        case " $* " in *" --ignore-scripts "*) ;; *) _ad_node_hooks ;; esac
        return
      fi ;;
    build|build:*) _ad_build command pnpm "$@"; return ;;
    run) case "${2:-}" in build|build:*) _ad_build command pnpm "$@"; return ;; esac ;;
  esac
  command pnpm "$@"
}

npx() {
  if [ "${1:-}" = next ] && [ "${2:-}" = build ]; then _ad_build command npx "$@"; return; fi
  command npx "$@"
}

composer() {
  if [ "${1:-}" = install ] && _ad_flags_only "${@:2}"; then
    _ad_install vendor "composer $* php=$(command php -r 'echo PHP_VERSION;' 2>/dev/null)" composer.json composer.lock -- command composer "$@" || return
    if [ "$_AD_REUSED" = 1 ]; then
      # The copied vendor/ skipped composer's scripts (Laravel package:discover...): run them.
      local a dump=(dump-autoload)
      for a in "${@:2}"; do
        case $a in
          --no-dev|--no-scripts|--classmap-authoritative|--apcu-autoloader|--no-interaction) dump+=("$a") ;;
          -a) dump+=(--classmap-authoritative) ;;
          -n) dump+=(--no-interaction) ;;
          -o|--optimize-autoloader) dump+=(--optimize) ;;
        esac
      done
      command composer "${dump[@]}"
      case " $* " in *" --no-scripts "*) ;; *)
        if grep -q '"post-install-cmd"' composer.json 2>/dev/null; then command composer run-script post-install-cmd; fi ;;
      esac
    fi
    return
  fi
  command composer "$@"
}
